import os, re, json, asyncio, uuid, time
from pathlib import Path
from datetime import datetime
from typing import Optional, List
from fastapi import FastAPI, UploadFile, File
from fastapi.responses import HTMLResponse, StreamingResponse
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
from exa_py import Exa
from cerebras.cloud.sdk import Cerebras

MODEL = "qwen-3-235b-a22b-instruct-2507"
INDEX_HTML = Path(__file__).parent / "index.html"

app = FastAPI(title="Tiffy Research Platform", version="2.0.0")
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_credentials=True, allow_methods=["*"], allow_headers=["*"])

exa_client = Exa(api_key=os.environ.get("EXA_API_KEY", ""))
cerebras_client = Cerebras(api_key=os.environ.get("CEREBRAS_API_KEY", ""))

# ── In-memory state ─────────────────────────────────────────────
sessions: dict = {}
audit_log: list = []
uploaded_files: dict = {}
server_start = datetime.now().isoformat()
counters = {"quick": 0, "deep": 0, "agentic": 0, "council": 0, "errors": 0, "total_sources": 0}

# ── Pydantic models ──────────────────────────────────────────────
class QueryReq(BaseModel):
    query: str
    session_id: Optional[str] = None
    file_ids: List[str] = []

class ClassifyReq(BaseModel):
    query: str

# ── Utilities ────────────────────────────────────────────────────
def now() -> str:
    return datetime.now().isoformat()

def new_id() -> str:
    return str(uuid.uuid4())[:8]

def sse(event: str, data: dict) -> str:
    return f"event: {event}\\ndata: {json.dumps(data, ensure_ascii=False)}\\n\\n"

def log_audit(type_: str, details: dict, session_id: str = None):
    audit_log.append({"id": new_id(), "timestamp": now(), "type": type_,
                       "session_id": session_id, "details": details})
    if len(audit_log) > 2000:
        del audit_log[:200]

def parse_json_array(text: str) -> list:
    for pattern in [r'\\[[\\s\\S]*?\\]']:
        m = re.search(pattern, text)
        if m:
            try:
                r = json.loads(m.group())
                if isinstance(r, list):
                    return r
            except Exception:
                pass
    return []

def parse_json_obj(text: str) -> dict:
    m = re.search(r'\\{[\\s\\S]*\\}', text)
    if m:
        try:
            r = json.loads(m.group())
            if isinstance(r, dict):
                return r
        except Exception:
            pass
    return {}

def make_source(r, n: int, subtopic: str = "") -> dict:
    url = r.url or ""
    try:
        domain = url.split("/")[2].replace("www.", "")
    except Exception:
        domain = url
    return {
        "n": n,
        "title": r.title or "Untitled",
        "url": url,
        "domain": domain,
        "summary": getattr(r, "summary", "") or "",
        "published_date": getattr(r, "published_date", None),
        "author": getattr(r, "author", None),
        "subtopic": subtopic,
        "favicon": f"",
    }

def file_context(file_ids: list) -> str:
    parts = []
    for fid in file_ids:
        if fid in uploaded_files:
            f = uploaded_files[fid]
            parts.append(f"=== File: {f['name']} ===\\n{f['content'][:4000]}")
    return "\\n\\n".join(parts)

def ensure_session(session_id: str = None) -> tuple:
    if session_id and session_id in sessions:
        return session_id, sessions[session_id], False
    sid = new_id()
    sess = {"id": sid, "title": None, "created_at": now(), "updated_at": now(),
            "messages": [], "source_count": 0}
    sessions[sid] = sess
    return sid, sess, True

def push_message(sid: str, role: str, content: str, mode: str = None,
                 sources: list = None, meta: dict = None):
    if sid not in sessions:
        return
    s = sessions[sid]
    msg = {"role": role, "content": content, "timestamp": now()}
    if mode: msg["mode"] = mode
    if sources: msg["sources"] = sources[:20]
    if meta: msg["meta"] = meta
    s["messages"].append(msg)
    s["updated_at"] = now()
    if not s["title"] and role == "user":
        s["title"] = content[:72] + ("…" if len(content) > 72 else "")

def cerebras_sync(messages: list, max_tokens: int = 800, temp: float = 0.7) -> str:
    r = cerebras_client.chat.completions.create(
        messages=messages, model=MODEL, stream=False,
        max_completion_tokens=max_tokens, temperature=temp, top_p=0.9)
    return r.choices[0].message.content or ""

SSE_HEADERS = {"Cache-Control": "no-cache", "X-Accel-Buffering": "no", "Connection": "keep-alive"}

# ── Serve frontend ───────────────────────────────────────────────
@app.get("/", response_class=HTMLResponse)
async def serve():
    return HTMLResponse(content=INDEX_HTML.read_text(encoding="utf-8"))

# ── Health ───────────────────────────────────────────────────────
@app.get("/api/health")
async def health():
    return {"status": "ok", "uptime_since": server_start, "sessions": len(sessions),
            "audit_events": len(audit_log), "uploaded_files": len(uploaded_files),
            "counters": counters}

# ── Classify ─────────────────────────────────────────────────────
@app.post("/api/classify")
async def classify(req: ClassifyReq):
    try:
        loop = asyncio.get_event_loop()
        text = await loop.run_in_executor(None, lambda: cerebras_sync([
            {"role": "system", "content": (
                "Classify the user's query into exactly one of these modes:\\n"
                "- quick: simple factual question, single answer needed\\n"
                "- deep: research topic needing comprehensive structured report\\n"
                "- agentic: complex multi-step task, goal-oriented, requires planning\\n"
                "- council: high-stakes or controversial question needing multiple perspectives\\n"
                "Output ONLY a JSON object: {\\"mode\\": \\"...\\", \\"reason\\": \\"...\\"}"
            )},
            {"role": "user", "content": req.query}
        ], max_tokens=120, temp=0.3))
        result = parse_json_obj(text)
        mode = result.get("mode", "quick")
        if mode not in ("quick", "deep", "agentic", "council"):
            mode = "quick"
        return {"mode": mode, "reason": result.get("reason", "")}
    except Exception as e:
        return {"mode": "quick", "reason": str(e)}

# ── Sessions ─────────────────────────────────────────────────────
@app.get("/api/sessions")
async def list_sessions():
    return sorted(sessions.values(), key=lambda s: s["updated_at"], reverse=True)

@app.post("/api/sessions")
async def create_session():
    sid = new_id()
    sess = {"id": sid, "title": None, "created_at": now(), "updated_at": now(),
            "messages": [], "source_count": 0}
    sessions[sid] = sess
    log_audit("session_create", {"session_id": sid})
    return sess

@app.get("/api/sessions/{sid}")
async def get_session(sid: str):
    if sid not in sessions:
        return {"error": "Not found"}, 404
    return sessions[sid]

@app.delete("/api/sessions/{sid}")
async def delete_session(sid: str):
    if sid in sessions:
        del sessions[sid]
        log_audit("session_delete", {"session_id": sid})
    return {"ok": True}

# ── Uploaded files ───────────────────────────────────────────────
@app.post("/api/upload")
async def upload(file: UploadFile = File(...)):
    try:
        content_bytes = await file.read()
        try:
            content = content_bytes.decode("utf-8")
        except Exception:
            content = content_bytes.decode("latin-1", errors="replace")
        fid = new_id()
        uploaded_files[fid] = {
            "id": fid, "name": file.filename,
            "size": len(content_bytes), "content": content,
            "uploaded_at": now(),
        }
        log_audit("file_upload", {"file_id": fid, "name": file.filename, "size": len(content_bytes)})
        return {"id": fid, "name": file.filename, "size": len(content_bytes), "chars": len(content)}
    except Exception as e:
        return {"error": str(e)}

@app.get("/api/files")
async def list_files():
    return [{"id": f["id"], "name": f["name"], "size": f["size"], "uploaded_at": f["uploaded_at"]}
            for f in uploaded_files.values()]

@app.delete("/api/files/{fid}")
async def delete_file(fid: str):
    if fid in uploaded_files:
        del uploaded_files[fid]
    return {"ok": True}

# ── Audit ────────────────────────────────────────────────────────
@app.get("/api/audit")
async def get_audit(limit: int = 200):
    return list(reversed(audit_log[-limit:]))

@app.get("/api/stats")
async def get_stats():
    return {"counters": counters, "server_start": server_start,
            "sessions": len(sessions), "uploaded_files": len(uploaded_files),
            "audit_events": len(audit_log)}

# ── QUICK SEARCH ─────────────────────────────────────────────────
@app.post("/api/search")
async def quick_search(req: QueryReq):
    query = req.query.strip()
    if not query:
        return {"error": "Empty query"}

    async def stream():
        sid, sess, is_new = ensure_session(req.session_id)
        yield sse("session", {"session_id": sid, "is_new": is_new})
        push_message(sid, "user", query, mode="quick")
        log_audit("query", {"mode": "quick", "query": query}, session_id=sid)
        counters["quick"] += 1

        try:
            loop = asyncio.get_event_loop()
            fctx = file_context(req.file_ids)

            exa_result = await loop.run_in_executor(
                None,
                lambda: exa_client.search_and_contents(
                    query, num_results=100, type="auto", summary=True))

            sources = []
            for i, r in enumerate(exa_result.results, 1):
                sources.append(make_source(r, i))

            counters["total_sources"] += len(sources)
            sessions[sid]["source_count"] = sessions[sid].get("source_count", 0) + len(sources)
            yield sse("sources", {"sources": sources})
            log_audit("retrieval", {"mode": "quick", "count": len(sources)}, session_id=sid)

            ctx_parts = []
            for s in sources[:20]:
                if s["summary"]:
                    ctx_parts.append(f"[{s['n']}] {s['title']}\\nURL: {s['url']}\\n{s['summary']}")
            context = "\\n\\n---\\n\\n".join(ctx_parts)
            if fctx:
                context = f"=== User-provided context ===\\n{fctx}\\n\\n=== Web sources ===\\n{context}"

            system = (
                "You are Tiffy, an elite AI research assistant with citation-first output discipline. "
                "Answer the user's question thoroughly using only the provided sources. "
                "Cite every factual claim with inline [n] notation matching source numbers. "
                "Use clean Markdown: **bold** key terms, bullet lists, headings (##, ###) where helpful. "
                "Never make claims without source support. If sources are insufficient, say so explicitly."
            )
            user_msg = f"Question: {query}\\n\\nSources:\\n\\n{context}\\n\\nProvide a thorough, fully-cited answer."

            full_text = ""
            cerebras_stream = cerebras_client.chat.completions.create(
                messages=[{"role": "system", "content": system}, {"role": "user", "content": user_msg}],
                model=MODEL, stream=True, max_completion_tokens=20000, temperature=1, top_p=0.8)

            for chunk in cerebras_stream:
                delta = chunk.choices[0].delta.content
                if delta:
                    full_text += delta
                    yield sse("token", {"token": delta})

            push_message(sid, "assistant", full_text, mode="quick", sources=sources[:10])
            log_audit("generation", {"mode": "quick", "tokens": len(full_text.split())}, session_id=sid)
            yield sse("done", {})

        except Exception as e:
            counters["errors"] += 1
            log_audit("error", {"mode": "quick", "error": str(e)}, session_id=sid)
            yield sse("error", {"error": str(e)})

    return StreamingResponse(stream(), media_type="text/event-stream", headers=SSE_HEADERS)

# ── DEEP RESEARCH ────────────────────────────────────────────────
@app.post("/api/deep")
async def deep_research(req: QueryReq):
    query = req.query.strip()
    if not query:
        return {"error": "Empty query"}

    async def stream():
        sid, sess, is_new = ensure_session(req.session_id)
        yield sse("session", {"session_id": sid, "is_new": is_new})
        push_message(sid, "user", query, mode="deep")
        log_audit("query", {"mode": "deep", "query": query}, session_id=sid)
        counters["deep"] += 1

        try:
            loop = asyncio.get_event_loop()
            fctx = file_context(req.file_ids)
            all_sources = []
            src_n = 0
            subtopic_results: dict = {}

            # Phase 1: Planning
            yield sse("status", {"text": "Analyzing your query and building research plan…", "phase": "planning"})

            plan_text = await loop.run_in_executor(None, lambda: cerebras_sync([
                {"role": "system", "content": (
                    "You are a research planning expert. Given a query, create exactly 6 distinct research sub-questions "
                    "covering: current state, recent developments, key actors/projects, technical depth, challenges/risks, "
                    "future outlook. Output ONLY a valid JSON array of 6 strings."
                )},
                {"role": "user", "content": f"Query: {query}"}
            ], max_tokens=600, temp=0.7))

            subtopics = parse_json_array(plan_text)
            if not subtopics:
                subtopics = [query]
            subtopics = [str(s) for s in subtopics[:7]]
            log_audit("plan", {"subtopics": subtopics}, session_id=sid)
            yield sse("plan", {"subtopics": subtopics})

            # Phase 2: Iterative retrieval
            for i, subtopic in enumerate(subtopics):
                yield sse("status", {"text": f"Retrieving: {subtopic}", "phase": "searching",
                                     "step": i + 1, "total": len(subtopics), "subtopic_index": i})

                try:
                    exa_result = await loop.run_in_executor(
                        None,
                        lambda st=subtopic: exa_client.search_and_contents(
                            st, num_results=100, type="auto", summary=True))
                except Exception as ex:
                    yield sse("subtopic_done", {"index": i, "error": str(ex)})
                    continue

                new_sources = []
                subtopic_results[subtopic] = []
                for r in exa_result.results:
                    src_n += 1
                    s = make_source(r, src_n, subtopic)
                    new_sources.append(s)
                    all_sources.append(s)
                    subtopic_results[subtopic].append((r, src_n))

                counters["total_sources"] += len(new_sources)
                yield sse("new_sources", {"sources": new_sources, "subtopic_index": i})
                yield sse("subtopic_done", {"index": i})

            # Phase 3: Reasoning / gap analysis
            yield sse("status", {"text": "Reasoning across sources and identifying gaps…", "phase": "reasoning"})

            gap_text = await loop.run_in_executor(None, lambda: cerebras_sync([
                {"role": "system", "content": (
                    "You are a critical research analyst. Given research coverage, identify 0-2 critical gaps. "
                    "Output ONLY a valid JSON array of targeted search queries (can be [])."
                )},
                {"role": "user", "content": (
                    f"Query: {query}\\nSubtopics covered:\\n" +
                    "\\n".join(f"- {s}" for s in subtopics) +
                    f"\\nTotal sources: {len(all_sources)}\\nIdentify 0-2 gap queries."
                )}
            ], max_tokens=250, temp=0.5))

            gap_queries = [str(q) for q in parse_json_array(gap_text) if str(q).strip()][:2]

            for gq in gap_queries:
                yield sse("status", {"text": f"Gap search: {gq}", "phase": "reasoning", "subtopic_index": -1})
                try:
                    gr = await loop.run_in_executor(
                        None,
                        lambda q=gq: exa_client.search_and_contents(
                            q, num_results=100, type="auto", summary=True))
                    new_sources = []
                    for r in gr.results:
                        src_n += 1
                        s = make_source(r, src_n, "gap")
                        new_sources.append(s)
                        all_sources.append(s)
                    counters["total_sources"] += len(new_sources)
                    yield sse("new_sources", {"sources": new_sources, "subtopic_index": -1})
                except Exception:
                    pass

            # Phase 4: Synthesis
            yield sse("status", {"text": "Synthesizing findings into comprehensive report…", "phase": "writing"})

            ctx_sections = []
            for subtopic, results in subtopic_results.items():
                lines = [f"### {subtopic}"]
                for r, n in results[:15]:
                    s = getattr(r, "summary", "") or ""
                    if s:
                        lines.append(f"[{n}] {r.title or 'Untitled'}\\nURL: {r.url}\\n{s[:400]}")
                if len(lines) > 1:
                    ctx_sections.append("\\n\\n".join(lines))

            if fctx:
                ctx_sections.insert(0, f"=== User-provided context ===\\n{fctx}")

            context = "\\n\\n---\\n\\n".join(ctx_sections)

            report_system = (
                "You are Tiffy, an elite AI research analyst with citation-first output discipline. "
                "Write a comprehensive, deeply analytical research report.\\n\\n"
                "Required sections:\\n"
                "## Executive Summary\\n"
                "## Key Findings (### sub-sections by theme)\\n"
                "## Cross-Source Analysis (patterns, agreements, contradictions)\\n"
                "## Uncertainties & Limitations\\n"
                "## Conclusion & Outlook\\n\\n"
                "Strict rules:\\n"
                "- Every factual claim cites [n] inline\\n"
                "- **Bold** all key terms and critical findings\\n"
                "- Use bullet points for lists\\n"
                "- Note source agreements and contradictions explicitly\\n"
                "- Be analytical and interpretive — not just descriptive"
            )

            full_text = ""
            cerebras_stream = cerebras_client.chat.completions.create(
                messages=[
                    {"role": "system", "content": report_system},
                    {"role": "user", "content": f"Research Query: {query}\\n\\nSources:\\n\\n{context}\\n\\nWrite the full report."}
                ],
                model=MODEL, stream=True, max_completion_tokens=20000, temperature=1, top_p=0.8)

            for chunk in cerebras_stream:
                delta = chunk.choices[0].delta.content
                if delta:
                    full_text += delta
                    yield sse("token", {"token": delta})

            sessions[sid]["source_count"] = sessions[sid].get("source_count", 0) + len(all_sources)
            push_message(sid, "assistant", full_text, mode="deep", sources=all_sources[:20])
            log_audit("generation", {"mode": "deep", "sources": len(all_sources), "tokens": len(full_text.split())}, session_id=sid)
            yield sse("done", {})

        except Exception as e:
            counters["errors"] += 1
            log_audit("error", {"mode": "deep", "error": str(e)}, session_id=sid)
            yield sse("error", {"error": str(e)})

    return StreamingResponse(stream(), media_type="text/event-stream", headers=SSE_HEADERS)

# ── AGENTIC MODE ─────────────────────────────────────────────────
@app.post("/api/agentic")
async def agentic_research(req: QueryReq):
    query = req.query.strip()
    if not query:
        return {"error": "Empty query"}

    async def stream():
        sid, sess, is_new = ensure_session(req.session_id)
        yield sse("session", {"session_id": sid, "is_new": is_new})
        push_message(sid, "user", query, mode="agentic")
        log_audit("query", {"mode": "agentic", "query": query}, session_id=sid)
        counters["agentic"] += 1

        try:
            loop = asyncio.get_event_loop()
            fctx = file_context(req.file_ids)
            all_sources = []
            src_n = 0

            # Phase 1: DAG planning
            yield sse("status", {"text": "Planning execution graph…", "phase": "planning"})

            plan_prompt = (
                f"You are an agentic research planner. Create a step-by-step execution plan.\\n\\n"
                f"Goal: {query}\\n"
                + (f"User context:\\n{fctx[:1000]}\\n\\n" if fctx else "")
                + "Output ONLY valid JSON with this exact structure:\\n"
                "{\\n"
                '  "goal": "brief goal",\\n'
                '  "steps": [\\n'
                '    {"id": "s1", "type": "search", "label": "human label", "query": "specific exa query", "depends_on": []},\\n'
                '    {"id": "s2", "type": "search", "label": "...", "query": "...", "depends_on": []},\\n'
                '    {"id": "s3", "type": "reflect", "label": "Analyze initial findings", "depends_on": ["s1","s2"]},\\n'
                '    {"id": "s4", "type": "search", "label": "...", "query": "...", "depends_on": ["s3"]},\\n'
                '    {"id": "s5", "type": "synthesize", "label": "Write final report", "depends_on": ["s3","s4"]}\\n'
                "  ]\\n"
                "}\\n"
                "Rules: max 8 steps total, first steps are parallel searches (no deps), "
                "intermediate reflect steps analyze data, last step is always type=synthesize."
            )

            plan_text = await loop.run_in_executor(None, lambda: cerebras_sync([
                {"role": "system", "content": "You are an expert AI task planner. Output ONLY valid JSON."},
                {"role": "user", "content": plan_prompt}
            ], max_tokens=900, temp=0.6))

            plan = parse_json_obj(plan_text)
            if not plan or "steps" not in plan:
                # fallback minimal plan
                plan = {"goal": query, "steps": [
                    {"id": "s1", "type": "search", "label": "Primary research", "query": query, "depends_on": []},
                    {"id": "s2", "type": "synthesize", "label": "Write report", "depends_on": ["s1"]}
                ]}

            steps = plan.get("steps", [])
            log_audit("plan", {"goal": plan.get("goal"), "steps": len(steps)}, session_id=sid)
            yield sse("plan", {"goal": plan.get("goal", query), "steps": steps})

            # Execute steps in order (respecting dependency levels)
            completed: dict = {}  # step_id -> result summary
            reflect_context = ""

            for step in steps:
                step_id = step.get("id", "?")
                step_type = step.get("type", "search")
                step_label = step.get("label", step_id)
                step_query = step.get("query", query)

                yield sse("step_start", {"id": step_id, "type": step_type, "label": step_label})
                yield sse("status", {"text": f"[{step_type.upper()}] {step_label}", "phase": "executing",
                                     "step_id": step_id})

                if step_type == "search":
                    try:
                        exa_result = await loop.run_in_executor(
                            None,
                            lambda q=step_query: exa_client.search_and_contents(
                                q, num_results=100, type="auto", summary=True))
                        new_sources = []
                        summaries = []
                        for r in exa_result.results:
                            src_n += 1
                            s = make_source(r, src_n, step_label)
                            new_sources.append(s)
                            all_sources.append(s)
                            if s["summary"]:
                                summaries.append(f"[{src_n}] {s['title']}: {s['summary'][:200]}")

                        counters["total_sources"] += len(new_sources)
                        yield sse("new_sources", {"sources": new_sources, "step_id": step_id})
                        completed[step_id] = f"Found {len(new_sources)} sources. Top summaries:\\n" + "\\n".join(summaries[:8])

                    except Exception as ex:
                        completed[step_id] = f"Search failed: {ex}"

                elif step_type == "reflect":
                    deps_data = "\\n\\n".join(completed.get(d, "") for d in step.get("depends_on", []))
                    reflect_text = await loop.run_in_executor(None, lambda dd=deps_data: cerebras_sync([
                        {"role": "system", "content": (
                            "You are an analytical research assistant. Analyze the gathered data, "
                            "identify key patterns, gaps, and insights. Output a concise analytical summary "
                            "that will guide further research. Be specific and actionable."
                        )},
                        {"role": "user", "content": f"Goal: {query}\\n\\nGathered data so far:\\n{dd}\\n\\nAnalyze findings and identify what's still needed."}
                    ], max_tokens=600, temp=0.6))
                    reflect_context = reflect_text
                    completed[step_id] = reflect_text
                    yield sse("reflect", {"id": step_id, "text": reflect_text})

                elif step_type == "synthesize":
                    yield sse("status", {"text": "Generating final report…", "phase": "writing", "step_id": step_id})

                    ctx_parts = []
                    if fctx:
                        ctx_parts.append(f"=== User context ===\\n{fctx}")
                    if reflect_context:
                        ctx_parts.append(f"=== Research analysis ===\\n{reflect_context}")

                    source_ctx = []
                    for s in all_sources[:80]:
                        if s["summary"]:
                            source_ctx.append(f"[{s['n']}] {s['title']}\\nURL: {s['url']}\\n{s['summary'][:350]}")
                    ctx_parts.append("=== Sources ===\\n" + "\\n\\n".join(source_ctx))
                    full_ctx = "\\n\\n---\\n\\n".join(ctx_parts)

                    synth_system = (
                        "You are Tiffy, an elite AI research analyst. Write a comprehensive, agentic research report.\\n\\n"
