@app.post("/api/council")
async def council_research(req: QueryReq):
    query = req.query.strip()
    if not query:
        return {"error": "Empty query"}

    async def stream():
        sid, sess, is_new = ensure_session(req.session_id)
        yield sse("session", {"session_id": sid, "is_new": is_new})
        push_message(sid, "user", query, mode="council")
        log_audit("query", {"mode": "council", "query": query}, session_id=sid)
        counters["council"] += 1

        try:
            loop = asyncio.get_event_loop()
            fctx = file_context(req.file_ids)
            all_sources = []
            src_n = 0

            yield sse("status", {"text": "Convening research council — 3 parallel perspectives…", "phase": "planning"})

            # Generate 3 council angles via Cerebras
            angles_text = await loop.run_in_executor(None, lambda: cerebras_sync([
                {"role": "system", "content": (
                    "You are a research council coordinator. For a given query, generate 3 distinct research angles:\\n"
                    "1. Factual/empirical: recent data, statistics, evidence\\n"
                    "2. Expert analysis: technical depth, specialist views, academic perspectives\\n"
                    "3. Broader context: historical background, societal implications, future outlook\\n"
                    "Output ONLY a valid JSON array of exactly 3 specific search query strings for Exa."
                )},
                {"role": "user", "content": f"Query: {query}"}
            ], max_tokens=300, temp=0.7))

            angles = parse_json_array(angles_text)
            if len(angles) < 3:
                angles = [
                    f"{query} data statistics evidence 2025",
                    f"{query} expert analysis technical deep dive",
                    f"{query} history context implications future"
                ]
            angles = angles[:3]

            council_labels = ["Empirical Evidence", "Expert Analysis", "Broader Context"]
            yield sse("council_plan", {"angles": [{"label": council_labels[i], "query": angles[i]} for i in range(3)]})

            # Run all 3 searches in parallel
            async def council_search(angle_q: str, angle_idx: int):
                try:
                    result = await loop.run_in_executor(
                        None,
                        lambda q=angle_q: exa_client.search_and_contents(
                            q, num_results=100, type="auto", summary=True))
                    return angle_idx, result.results
                except Exception:
                    return angle_idx, []

            yield sse("status", {"text": "Running 3 parallel searches across all perspectives…", "phase": "searching"})
            search_tasks = await asyncio.gather(
                council_search(angles[0], 0),
                council_search(angles[1], 1),
                council_search(angles[2], 2),
            )

            council_contexts = {}
            for angle_idx, results in search_tasks:
                new_sources = []
                ctx_lines = []
                label = council_labels[angle_idx]
                for r in results:
                    src_n += 1
                    s = make_source(r, src_n, label)
                    new_sources.append(s)
                    all_sources.append(s)
                    if s["summary"]:
                        ctx_lines.append(f"[{src_n}] {s['title']}\\nURL: {s['url']}\\n{s['summary'][:350]}")
                counters["total_sources"] += len(new_sources)
                council_contexts[label] = "\\n\\n".join(ctx_lines[:15])
                yield sse("new_sources", {"sources": new_sources, "angle": label, "angle_index": angle_idx})
                yield sse("status", {"text": f"{label}: {len(new_sources)} sources gathered", "phase": "searching",
                                     "angle_index": angle_idx})

            # Individual council member syntheses (non-streaming, fast)
            yield sse("status", {"text": "Council members deliberating…", "phase": "reasoning"})

            member_summaries = []
            for label, ctx in council_contexts.items():
                if not ctx.strip():
                    continue
                member_text = await loop.run_in_executor(None, lambda l=label, c=ctx: cerebras_sync([
                    {"role": "system", "content": (
                        f"You are the '{l}' council member. Write a focused 3-4 paragraph analytical brief "
                        f"on this topic from your specific perspective. Cite sources with [n]. "
                        f"Include your most critical insight and any strong positions."
                    )},
                    {"role": "user", "content": f"Topic: {query}\\n\\nYour sources:\\n{c}"}
                ], max_tokens=800, temp=0.7))
                member_summaries.append({"label": label, "text": member_text})
                yield sse("council_member", {"label": label, "text": member_text})

            # Final unified synthesis
            yield sse("status", {"text": "Synthesizing council consensus and divergence…", "phase": "writing"})

            members_block = "\\n\\n".join(
                f"=== {m['label']} ===\\n{m['text']}" for m in member_summaries
            )

            full_source_ctx = []
            for s in all_sources[:80]:
                if s["summary"]:
                    full_source_ctx.append(f"[{s['n']}] {s['title']}\\nURL: {s['url']}\\n{s['summary'][:300]}")
            source_block = "\\n\\n".join(full_source_ctx)

            if fctx:
                source_block = f"=== User context ===\\n{fctx}\\n\\n{source_block}"

            synth_system = (
                "You are the Chief Council Synthesizer for Tiffy Research. "
                "You have received briefs from 3 council members with different research perspectives. "
                "Write a unified, authoritative research report.\\n\\n"
                "Required structure:\\n"
                "## Council Summary\\n"
                "## Points of Consensus (where all perspectives agree)\\n"
                "## Points of Divergence (where perspectives differ — analyze why)\\n"
                "## Unified Analysis (your synthesis of all evidence)\\n"
                "## Confidence Assessment (what we know with high/medium/low confidence)\\n"
                "## Conclusions\\n\\n"
                "Rules: cite all claims with [n] from the source list, **bold** key findings, "
                "acknowledge uncertainty explicitly, be authoritative but calibrated."
            )

            full_text = ""
            cerebras_stream = cerebras_client.chat.completions.create(
                messages=[
                    {"role": "system", "content": synth_system},
                    {"role": "user", "content": (
                        f"Query: {query}\\n\\n"
                        f"Council Member Briefs:\\n{members_block}\\n\\n"
                        f"Full source list:\\n{source_block}\\n\\n"
                        f"Write the unified council report."
                    )}
                ],
                model=MODEL, stream=True, max_completion_tokens=20000, temperature=1, top_p=0.8)

            for chunk in cerebras_stream:
                delta = chunk.choices[0].delta.content
                if delta:
                    full_text += delta
                    yield sse("token", {"token": delta})

            sessions[sid]["source_count"] = sessions[sid].get("source_count", 0) + len(all_sources)
            push_message(sid, "assistant", full_text, mode="council", sources=all_sources[:20])
            log_audit("generation", {"mode": "council", "sources": len(all_sources),
                                     "angles": len(member_summaries)}, session_id=sid)
            yield sse("done", {})

        except Exception as e:
            counters["errors"] += 1
            log_audit("error", {"mode": "council", "error": str(e)}, session_id=sid)
            yield sse("error", {"error": str(e)})

    return StreamingResponse(stream(), media_type="text/event-stream", headers=SSE_HEADERS)

